import json, sys, re, collections

corpus = sys.argv[1]
d = json.load(open(f"/tmp/claude-501/t155/{corpus}.NEW.json")) if len(sys.argv) < 3 else json.load(open(sys.argv[2]))
msgs = []


def walk(o):
    if isinstance(o, dict):
        for k, v in o.items():
            if k in ("diagnostics", "warnings") and isinstance(v, list):
                for x in v:
                    if isinstance(x, dict) and x.get("code") == "SKIPPED_CANDIDATE":
                        msgs.append(x)
            walk(v)
    elif isinstance(o, list):
        for x in o:
            walk(x)


walk(d)
kinds = collections.Counter()
for m in msgs:
    t = m["message"]
    if "declared inside a function body" in t:
        kinds["inside function body"] += 1
    elif "matched no known component pattern" in t:
        kinds["pascal binding no pattern"] += 1
    else:
        kinds[re.sub(r"'[^']*'", "'X'", t)[:90]] += 1
for k, v in kinds.most_common():
    print(v, k)
pat = [m for m in msgs if "matched no known component pattern" in m["message"]]
