def strip(o):
    if isinstance(o, dict):
        return {k: strip(v) for k, v in o.items() if k not in ("diagnostics", "warnings", "durationMs", "duration_ms")}
    if isinstance(o, list):
        return [strip(x) for x in o]
    return o


